import { IndexedMinHeap } from "#base/scripts/heap.js";
import { HexMap, HexTile } from "#base/scripts/hex-map.js";
import { profileFunction, profileScope } from "#base/scripts/profiling.js";
import { TerrainType } from "#base/scripts/voronoi-types.js";
import { VoronoiUtils, WrapDistOptions, WrapType } from "#base/scripts/voronoi-utils.js";

export class PlayerRegion {
	id = -1;
	playerAreas = 0;
	filter: (tile: HexTile) => boolean = (tile: HexTile) => tile.playerLandmassId == this.id;
}

// =============================================================================
// CreateMajorPlayerAreas
// =============================================================================
//
// Pipeline per landmass:
//   1. buildLandmassContext   - layer per-landmass masks onto the map context.
//   2. keepLargestComponent   - flood-fill, drop enclaves cut off by mountains.
//   3. kmeansRelaxSeeds       - Gonzalez algorithm to find initial region seeds
//                               plus Lloyd polish for K seeds.
//   4. powerDiagramPartition  - bias-adjusted multi-source Dijkstra. Each
//                               region gets a scalar bias; iterate Dijkstra
//                               and bias updates until per-region total tile
//                               value converges. Output is a connected,
//                               value-balanced, shape-compact partition.
//   5. writeBack              - commit assignments to HexMap.
//
// Phases run on typed-array views of per-tile state and never touch
// HexMap/HexTile in the hot loops. Map-invariant data (terrain, positions,
// neighbor table) lives in `MapContext`, built once per driver call;
// per-landmass masks are layered on top in `LandmassContext`. Heaps use
// `IndexedMinHeap` (Float64 keys, Uint32 indices) to avoid per-entry
// allocation.

// Phases emit per-pass / per-iter progress logs when true.
const detailedLogs = false;

// Flat tile arrays are length `width * height`, indexed as `y * width + x`.
// Tiles outside the current landmass are masked off via `inLandmass` after
// keepLargestComponent; phases that walk neighbors skip indices where
// `passable[idx] === 0`.

// Map-invariant snapshot. Built once per CreateMajorPlayerAreas call and
// shared across all landmasses on the map. Phase code never mutates these
// arrays, so they can be safely aliased into every LandmassContext.
interface MapContext {
	width: number;
	height: number;

	// Read-only per-tile snapshot pulled from HexMap up front.
	terrain: Uint8Array; // TerrainType, used for cost and passable checks
	posX: Float32Array; // tile center x (for k-means centroid computation)
	posY: Float32Array; // tile center y

	// Hex neighbor table. For each tile flat-idx, the 6 consecutive entries
	// at `neighbors[idx*6 .. idx*6+6)` hold the flat indices of its up-to-6
	// hex neighbors, or -1 for off-map (or off-edge in non-wrapping
	// directions). Lets the Dijkstra inner loop replace parity branching,
	// dx/dy lookup, bounds checks, and wrap math with one typed-array read.
	neighbors: Int32Array;
}

// Per-landmass view: extends MapContext with the masks/scratch that change
// each loop iteration. Mask arrays are sized `width * height` so phases can
// index them with the same flat index used everywhere else.
interface LandmassContext extends MapContext {
	// Filtered membership for the current landmass.
	inLandmass: Uint8Array; // 1 if tile belongs to this landmass after flood-fill, else 0
	passable: Uint8Array; // 1 if `inLandmass` and tile is passable, else 0

	// Per-tile region assignment. -1 = unassigned, 0..numRegions-1 otherwise.
	// Used as scratch by k-means and as the final output for writeBack.
	assignment: Int32Array;
}

// A set of tiles within a landmass, stored as flat indices (`y * width + x`).
// Same encoding used by the heap and seed arrays so no conversion is needed
// between phases.
interface LandmassTiles {
	tiles: Uint32Array;
}

// Snapshot terrain/position/neighbor data shared across landmasses. The
// neighbor table dominates: tileCount * 6 Int32 entries plus per-tile
// parity branching. Building it once per map keeps the per-landmass cost
// down to one filter sweep.
function buildMapContext(hexMap: HexMap, wrap: WrapDistOptions): MapContext {
	const tiles = hexMap.getTiles();
	const height = tiles.length;
	const width = height > 0 ? tiles[0].length : 0;
	const tileCount = width * height;

	const terrain = new Uint8Array(tileCount);
	const posX = new Float32Array(tileCount);
	const posY = new Float32Array(tileCount);

	for (let y = 0; y < height; ++y) {
		const row = tiles[y];
		const rowOffset = y * width;
		for (let x = 0; x < width; ++x) {
			const tile = row[x];
			const idx = rowOffset + x;
			terrain[idx] = tile.terrainType;
			posX[idx] = tile.pos.x;
			posY[idx] = tile.pos.y;
		}
	}

	const evenDeltas = hexMap.EvenRowDeltas;
	const oddDeltas = hexMap.OddRowDeltas;
	const evenDx = new Int8Array(6);
	const evenDy = new Int8Array(6);
	const oddDx = new Int8Array(6);
	const oddDy = new Int8Array(6);
	for (let i = 0; i < 6; ++i) {
		evenDx[i] = evenDeltas[i][0];
		evenDy[i] = evenDeltas[i][1];
		oddDx[i] = oddDeltas[i][0];
		oddDy[i] = oddDeltas[i][1];
	}

	// Build the flat-index neighbor table. Each tile gets 6 consecutive
	// entries; -1 marks off-map (or off-edge along a non-wrapping axis).
	// Y wrap assumes an even row count so parity is preserved across the
	// seam -- the dx/dy table picked for the source row stays valid at the
	// wrapped destination.
	const wrapMask = wrap.wrap ?? WrapType.None;
	const wrapX = (wrapMask & WrapType.WrapX) !== 0;
	const wrapY = (wrapMask & WrapType.WrapY) !== 0;
	const neighbors = new Int32Array(tileCount * 6);
	for (let y = 0; y < height; ++y) {
		const dx = (y & 1) === 0 ? evenDx : oddDx;
		const dy = (y & 1) === 0 ? evenDy : oddDy;
		for (let x = 0; x < width; ++x) {
			const base = (y * width + x) * 6;
			for (let i = 0; i < 6; ++i) {
				let ny = y + dy[i];
				if (ny < 0 || ny >= height) {
					if (!wrapY) {
						neighbors[base + i] = -1;
						continue;
					}
					ny = ny < 0 ? ny + height : ny - height;
				}
				let nx = x + dx[i];
				if (nx < 0 || nx >= width) {
					if (!wrapX) {
						neighbors[base + i] = -1;
						continue;
					}
					nx = nx < 0 ? nx + width : nx - width;
				}
				neighbors[base + i] = ny * width + nx;
			}
		}
	}

	return { width, height, terrain, posX, posY, neighbors };
}

// Phase 1: layer per-landmass masks/scratch onto the shared map context.
// Walks the map once to evaluate `region.filter` and record passability.
function buildLandmassContext(mapCtx: MapContext, hexMap: HexMap, region: PlayerRegion): LandmassContext {
	const { width, height } = mapCtx;
	const tileCount = width * height;
	const inLandmass = new Uint8Array(tileCount);
	const passable = new Uint8Array(tileCount);
	const assignment = new Int32Array(tileCount);
	assignment.fill(-1);

	const tiles = hexMap.getTiles();
	const filter = region.filter;
	for (let y = 0; y < height; ++y) {
		const row = tiles[y];
		const rowOffset = y * width;
		for (let x = 0; x < width; ++x) {
			const tile = row[x];
			if (filter(tile)) {
				const idx = rowOffset + x;
				inLandmass[idx] = 1;
				if (tile.isPassable()) {
					passable[idx] = 1;
				}
			}
		}
	}

	return { ...mapCtx, inLandmass, passable, assignment };
}

// Phase 2: flood-fill over `passable` tiles, keep the largest connected
// component, zero out `inLandmass`/`passable` on smaller components. Returns
// the flat indices of the kept component.
function keepLargestComponent(ctx: LandmassContext): LandmassTiles {
	const { width, height, passable, inLandmass, neighbors } = ctx;
	const tileCount = passable.length;

	// 0 means unvisited; otherwise stores 1-based component id.
	const componentId = new Uint16Array(tileCount);
	const stack = new Uint32Array(tileCount);

	let nextId = 0;
	let bestId = 0;
	let bestSize = 0;

	for (let tileY = 0; tileY < height; ++tileY) {
		const tileRow = tileY * width;
		for (let tileX = 0; tileX < width; ++tileX) {
			const tileIdx = tileRow + tileX;
			if (passable[tileIdx] === 0 || componentId[tileIdx] !== 0) continue;

			++nextId;
			let stackTop = 0;
			let size = 0;
			stack[stackTop++] = tileIdx;
			componentId[tileIdx] = nextId;

			while (stackTop > 0) {
				const idx = stack[--stackTop];
				++size;
				const base = idx * 6;
				for (let i = 0; i < 6; ++i) {
					const nIdx = neighbors[base + i];
					if (nIdx < 0) continue;
					if (passable[nIdx] === 1 && componentId[nIdx] === 0) {
						componentId[nIdx] = nextId;
						stack[stackTop++] = nIdx;
					}
				}
			}

			if (size > bestSize) {
				bestSize = size;
				bestId = nextId;
			}
		}
	}

	const tiles = new Uint32Array(bestSize);
	let w = 0;
	for (let y = 0; y < height; ++y) {
		const rowOffset = y * width;
		for (let x = 0; x < width; ++x) {
			const i = rowOffset + x;
			// Non-landmass tiles already have inLandmass/passable == 0; only
			// landmass tiles need their masks updated or their flat-idx kept.
			if (inLandmass[i] === 0) continue;
			if (componentId[i] === bestId) {
				tiles[w++] = i;
			} else {
				inLandmass[i] = 0;
				passable[i] = 0;
			}
		}
	}
	return { tiles };
}

// Phase 3: pick K seed positions for the bias-loop partition.
//
// Two stages:
//   1. Gonzalez farthest-point seeding. Seed 0 is arbitrary; seed j is the
//      argmax of distance-to-nearest-already-placed seed, which lands seeds
//      at landmass extremes.
//   2. Lloyd polish. Multi-source Dijkstra, per-region centroid, snap each
//      seed to the in-region tile nearest its centroid. Usually 1-2 passes.
//
// Gonzalez alone clusters seeds on the perimeter (poor for value balance);
// Lloyd alone struggles to spread seeds on chunky or concave landmasses.
// Together: Gonzalez gives spread, Lloyd pulls seeds toward centroids.
//
// Cost: Gonzalez is roughly N * (1 + 1/2 + ... + 1/K) (the K-th harmonic
// number, ~2.3 for K=5), not N * K -- bestDist and the heap persist
// across seed picks so seed j only revisits tiles closer to it than to
// seeds 0..j-1. Plus 1-2 Lloyd passes at N each.
//
// Side effect: leaves `ctx.assignment` filled with the last unbiased
// nearest-seed partition. The bias loop in phase 4 overwrites it on iter 0.
function kmeansRelaxSeeds(
	ctx: LandmassContext,
	landmassTiles: LandmassTiles,
	numRegions: number,
	maxPasses: number,
): Uint32Array {
	const { width, terrain, passable, assignment, posX, posY, neighbors } = ctx;
	const { tiles } = landmassTiles;

	const seeds = new Uint32Array(numRegions);
	const prevSeeds = new Uint32Array(numRegions);
	const prevPrevSeeds = new Uint32Array(numRegions);

	const bestDist = new Float32Array(passable.length);
	const heap = new IndexedMinHeap(tiles.length);
	const centroidX = new Float64Array(numRegions);
	const centroidY = new Float64Array(numRegions);
	const regionCount = new Int32Array(numRegions);
	const bestD = new Float64Array(numRegions);
	const bestSeed = new Uint32Array(numRegions);

	// Plain multi-source Dijkstra.
	// Coast tiles cost 2, all other passable tiles cost 1; off-map and
	// impassable neighbors are skipped.
	const dijkstra = (): void => {
		while (heap.size > 0) {
			const idx = heap.pop();
			const dist = heap.lastVal;
			if (dist > bestDist[idx]) continue;
			const regionId = assignment[idx];
			const base = idx * 6;
			for (let i = 0; i < 6; ++i) {
				const nIdx = neighbors[base + i];
				if (nIdx < 0 || passable[nIdx] === 0) continue;
				const cost = terrain[nIdx] === TerrainType.Coast ? 2 : 1;
				const newDist = dist + cost;
				if (newDist < bestDist[nIdx]) {
					bestDist[nIdx] = newDist;
					assignment[nIdx] = regionId;
					heap.push(newDist, nIdx);
				}
			}
		}
	};

	// Stage 1: Gonzalez farthest-point seeding. bestDist and the heap persist
	// across seed picks; the heap drain after each new seed only updates
	// tiles strictly closer to it. After all K seeds are placed,
	// `assignment[idx]` holds the nearest-seed region for every landmass tile.
	bestDist.fill(Infinity);
	assignment.fill(-1);
	heap.clear();

	seeds[0] = tiles[0];
	bestDist[seeds[0]] = 0;
	assignment[seeds[0]] = 0;
	heap.push(0, seeds[0]);

	for (let j = 0; j < numRegions; ++j) {
		if (j > 0) {
			// Pick the landmass tile with the largest distance to the nearest
			// already-placed seed. Linear scan over `tiles`; the heap can't help
			// since we need argmax, not pop-min.
			let farthestIdx = tiles[0];
			let farthestDist = -1;
			for (const idx of tiles) {
				const d = bestDist[idx];
				if (d > farthestDist) {
					farthestDist = d;
					farthestIdx = idx;
				}
			}
			seeds[j] = farthestIdx;
			bestDist[farthestIdx] = 0;
			assignment[farthestIdx] = j;
			heap.push(0, farthestIdx);
		}
		// Drain the heap. For j=0 this is a full Dijkstra; for j>0 most
		// tiles already have bestDist < newSeed's reach and the heap
		// runs out quickly.
		dijkstra();
	}

	if (detailedLogs) {
		console.log(
			`  Gonzalez seeding: seeds at [${Array.from(seeds, (s) => `(${s % width},${(s / width) | 0})`).join(", ")}]`,
		);
	}

	// Convergence threshold (squared world distance): stop when no seed moves
	// more than ~1 hex between passes. Hex spacing is ~1 world unit, so 1.0
	// means "seeds settled within a single neighbor". Tighter thresholds only
	// catch sub-hex movement, which the bias loop absorbs cheaply at the cost
	// of another full Dijkstra per pass.
	const moveThresholdSq = 1.0;

	// Stage 2: Lloyd relaxation. Pass 0 reuses the Gonzalez nearest-seed
	// partition (already in `assignment`) and skips straight to the
	// centroid/snap step.
	let passesRun = 0;
	let exitReason = "max passes";
	for (let pass = 0; pass < maxPasses; ++pass) {
		if (pass > 0) {
			bestDist.fill(Infinity);
			assignment.fill(-1);
			heap.clear();
			for (let j = 0; j < numRegions; ++j) {
				const idx = seeds[j];
				bestDist[idx] = 0;
				assignment[idx] = j;
				heap.push(0, idx);
			}
			dijkstra();
		}

		// Per-region centroid in world (x, y) coordinates.
		centroidX.fill(0);
		centroidY.fill(0);
		regionCount.fill(0);
		for (const idx of tiles) {
			const r = assignment[idx];
			centroidX[r] += posX[idx];
			centroidY[r] += posY[idx];
			++regionCount[r];
		}
		for (let j = 0; j < numRegions; ++j) {
			if (regionCount[j] === 0) continue;
			centroidX[j] /= regionCount[j];
			centroidY[j] /= regionCount[j];
		}

		// Snap each seed to the assigned-region tile nearest its centroid
		// (squared world distance). Restricting to same-region tiles keeps
		// seeds inside their own cells on concave landmasses.
		bestD.fill(Infinity);
		for (const idx of tiles) {
			const r = assignment[idx];
			const ddx = posX[idx] - centroidX[r];
			const ddy = posY[idx] - centroidY[r];
			const d = ddx * ddx + ddy * ddy;
			if (d < bestD[r]) {
				bestD[r] = d;
				bestSeed[r] = idx;
			}
		}

		// Promote seed history (for the 2-cycle detector below) and measure
		// per-seed movement. Use world-space distance, not tile equality:
		// adjacent tiles can be sub-hex apart, so "different tile" doesn't
		// imply "actually moved".
		let maxMoveSq = 0;
		let anyChanged = false;
		for (let j = 0; j < numRegions; ++j) {
			prevPrevSeeds[j] = prevSeeds[j];
			prevSeeds[j] = seeds[j];
			if (regionCount[j] === 0) continue;
			const newSeed = bestSeed[j];
			const oldSeed = seeds[j];
			if (newSeed !== oldSeed) {
				anyChanged = true;
				const ddx = posX[newSeed] - posX[oldSeed];
				const ddy = posY[newSeed] - posY[oldSeed];
				const dsq = ddx * ddx + ddy * ddy;
				if (dsq > maxMoveSq) maxMoveSq = dsq;
				seeds[j] = newSeed;
			}
		}
		++passesRun;

		if (detailedLogs) {
			console.log(
				`  K-means pass ${pass}: counts=[${Array.from(regionCount).join(", ")}], maxSeedMove=${Math.sqrt(maxMoveSq).toFixed(2)}`,
			);
		}

		if (!anyChanged) {
			exitReason = "no movement";
			break;
		}
		if (maxMoveSq < moveThresholdSq) {
			exitReason = "converged";
			break;
		}
		// 2-cycle detection: if every region's seed matches its position two
		// passes ago, we're oscillating between two centroidal configurations
		// and won't reach a fixed point. Common on K=5+ landmasses where two
		// regions trade a border tile back and forth each pass. Either seed
		// set is as good as the other, so just stop.
		if (pass >= 2) {
			let isCycle = true;
			for (let j = 0; j < numRegions; ++j) {
				if (seeds[j] !== prevPrevSeeds[j]) {
					isCycle = false;
					break;
				}
			}
			if (isCycle) {
				exitReason = "2-cycle";
				break;
			}
		}
	}

	if (detailedLogs) {
		console.log(
			`K-means relaxation: ${passesRun} pass(es), exit=${exitReason}, seeds at [${Array.from(seeds, (s) => `(${s % width},${(s / width) | 0})`).join(", ")}]`,
		);
	}
	return seeds;
}

// Phase 4: bias-adjusted multi-source Dijkstra ("power diagram"). Each region
// gets a scalar `bias[j]`; seeds are entered into the heap with starting
// distance `-bias[j]`, so a higher bias makes that region's cells extend
// farther. Each iteration: run Dijkstra, measure per-region total tile value,
// nudge biases toward the global mean. Output is a connected, compact,
// value-balanced partition left in `ctx.assignment`.
function powerDiagramPartition(
	ctx: LandmassContext,
	landmassTiles: LandmassTiles,
	seeds: Uint32Array,
	numRegions: number,
	tileValue: (idx: number) => number,
	maxIters: number,
): void {
	const { terrain, passable, assignment, neighbors } = ctx;
	const { tiles } = landmassTiles;

	// Precompute and cache per-tile value scores. tileValue() may cross the
	// C++ bridge or do per-call index unpacking (div/mod into the HexTile
	// grid); calling it once per tile per iter dominates this phase. We pay
	// it once up front, fold the total-value sum into the same pass, and
	// then read the iter loop's value measurements from a flat Float64Array.
	// Indexed parallel to `tiles` (cache[i] is the value of tiles[i]) rather
	// than by flat tile index, so it stays compact on sparse landmasses.
	const tileValueCache = new Float64Array(tiles.length);
	let totalLandmassValue = 0;
	for (let i = 0; i < tiles.length; ++i) {
		const v = tileValue(tiles[i]);
		tileValueCache[i] = v;
		totalLandmassValue += v;
	}
	const targetValue = totalLandmassValue / numRegions;
	const avgTileValue = totalLandmassValue / tiles.length;

	// Exit early once the worst-case region imbalance is small enough that
	// further iters would be polishing noise. 10% of the target value means
	// no region is more than ~one starting-area's-worth out of balance
	// relative to the equal share.
	const earlyExitSpread = 0.1 * targetValue;

	// Persistent scratch for the iter loop below.
	const bias = new Float64Array(numRegions);
	const totalValue = new Float64Array(numRegions);
	// Snapshots of bias and totalValue from the prior iter, used by the
	// refit block to compute single-iter deltas. Captured at the end of
	// each iter, before the bias update.
	const prevBias = new Float64Array(numRegions);
	const prevTotalValue = new Float64Array(numRegions);
	const bestDist = new Float64Array(passable.length);
	const heap = new IndexedMinHeap(tiles.length);

	// Best-so-far snapshot. The bias dynamics aren't strictly monotone (they
	// oscillate as boundary tiles flip in discrete jumps; 2-cycles are
	// common), so we keep the lowest-spread assignment we've seen and
	// restore it on exit.
	const bestAssignment = new Int32Array(assignment.length);
	let bestSpread = Infinity;
	let itersSinceBest = 0;

	// Bias-step sizing. After each iter we adjust each region's bias[j]
	// to transfer (targetValue - totalValue[j]) tiles' worth of value into
	// region j on the next iter. transferCoeff is the conversion factor
	// (value transferred per unit of bias change):
	//   deltaBias = damping * imbalance / transferCoeff
	//
	// Initial estimate (disk model): treat the landmass as a disk of N
	// tiles (radius R = sqrt(N/pi)) cut into K wedges. Raising bias[j] by
	// delta moves wedge j's interior boundary outward by delta cost-units,
	// transferring ~(boundary length) * delta tiles. We use 1.3 R for the
	// boundary -- the perfect-disk value of 2R over-estimates real
	// landmasses, which are concave and irregular. Multiply by
	// avgTileValue to get value transferred per unit of bias.
	//
	// The disk model is only a starting point. Each iter we observe an
	// actual (dBias, dValue) sample and blend transferCoeff toward it via
	// a running average (see refit block in the loop). Damping is a
	// separate, faster-adapting knob layered on top: it halves on
	// overshoot and grows toward maxDamping on improvement. Damping
	// absorbs an effect transferCoeff can't model on its own: all K
	// regions update their biases simultaneously from the same
	// partition, so each region's actual value change depends on its
	// neighbors' bias changes too. transferCoeff is a single scalar and
	// can't capture that cross-region coupling, so when the coupling
	// causes overshoot, damping shrinks the step until things settle.
	// maxBiasDelta caps the absolute step as a final backstop.
	const radius = Math.sqrt(tiles.length / Math.PI);
	const perimeterEstimate = Math.max(1, 1.3 * radius);
	const diskCoeff = Math.max(0.01, perimeterEstimate * avgTileValue);
	// Single-iter observations get clamped against the disk-model anchor
	// rather than the running coeff. Per-iter clamps would compound across
	// iters (5 iters of 2x = 32x range); anchoring to diskCoeff keeps the
	// search bounded regardless of history.
	const coeffLo = diskCoeff * 0.5;
	const coeffHi = diskCoeff * 2.0;
	let transferCoeff = diskCoeff;
	// Running-average blend weight: alpha = 1 / (1 + confidence). Each
	// new sample contributes `alpha` to the updated estimate, so larger
	// confidence -> smaller alpha -> more weight on history. Starting
	// confidence at 1 (rather than 0) means iter 1's sample blends 50/50
	// with the disk prior -- enough to react fast, not enough for one
	// noisy observation to swing the estimate to a clamp boundary. Each
	// accepted sample increments confidence (alpha shrinks to 1/3, 1/4,
	// ...) so well-converged estimates resist late-iter noise. Capped at
	// 8 (alpha floor 1/9) so the estimate never freezes entirely.
	// Overshoot iters skip the update without bumping confidence: their
	// observations come from a disturbed regime and aren't valid samples.
	let calibrationConfidence = 1;
	const calibrationConfidenceCap = 8;
	const maxBiasDelta = 10.0;
	const stagnationLimit = 3;
	const minDamping = 0.1;
	// Allow undamped updates (damping = 1.0). Centroidal seeds from
	// k-means leave the starting partition well-balanced, so the bias
	// loop runs in a near-linear regime where cross-region coupling is
	// mild and full-size steps stay well below unstable. Adaptive halving
	// plus best-snapshot rollback below recovers from any overshoot.
	const maxDamping = 1.0;
	let damping = maxDamping;
	let prevSpread = Infinity;

	// Per-(tile, region) deterministic jitter. Without it, many boundary
	// tiles have effectively-tied costs and a small bias shift flips either
	// none (plateau) or all (overshoot). Jitter is charged on tile entry and
	// refunded on exit (telescoping) so the net stored priority is
	// `pathCost - bias[j] + jitter(tile, j)` and it doesn't accumulate along
	// long paths. Magnitude must stay below the min edge cost (1) to keep
	// Dijkstra edges non-negative. Quality requirement is low (adjacent
	// (tile, region) pairs should land in different parts of [0,1)), so a
	// single Knuth multiply suffices. Assumes numRegions <= 16 so
	// `idx * 16 + regionId` is a unique key.
	const jitterMagnitude = 0.5;
	const jitterScale = jitterMagnitude / 0x100000000;
	const jitterAt = (idx: number, regionId: number): number => {
		return (Math.imul(idx * 16 + regionId, 0x9e3779b9) >>> 0) * jitterScale;
	};

	for (let iter = 0; iter < maxIters; ++iter) {
		// Reset per-iteration scratch.
		bestDist.fill(Infinity);
		assignment.fill(-1);
		heap.clear();

		// Seed each region with starting distance -bias[j] + jitter(seed, j).
		// Negative starting distances are fine: edge costs are non-negative
		// (jitter magnitude < 1 ensures this) so Dijkstra remains correct on
		// the shifted scale.
		for (let j = 0; j < numRegions; ++j) {
			const idx = seeds[j];
			const seedDist = -bias[j] + jitterAt(idx, j);
			bestDist[idx] = seedDist;
			assignment[idx] = j;
			heap.push(seedDist, idx);
		}

		// Multi-source Dijkstra. Stale entries are detected via bestDist; the
		// popped tile's regionId is read from `assignment` (a non-stale entry
		// still has assignment[idx] equal to the regionId that pushed it,
		// since a strictly-better push is what would have made it stale).
		while (heap.size > 0) {
			const idx = heap.pop();
			const dist = heap.lastVal;
			if (dist > bestDist[idx]) continue;
			const regionId = assignment[idx];
			const jitterU = jitterAt(idx, regionId);
			const base = idx * 6;
			for (let i = 0; i < 6; ++i) {
				const nIdx = neighbors[base + i];
				if (nIdx < 0 || passable[nIdx] === 0) continue;
				const cost = terrain[nIdx] === TerrainType.Coast ? 2 : 1;
				// Telescoping jitter: refund u's jitter, charge v's jitter.
				// Net stored priority = pathCost - bias + jitter(v, region).
				const newDist = dist + cost + jitterAt(nIdx, regionId) - jitterU;
				if (newDist < bestDist[nIdx]) {
					bestDist[nIdx] = newDist;
					assignment[nIdx] = regionId;
					heap.push(newDist, nIdx);
				}
			}
		}

		// Measure per-region total value.
		totalValue.fill(0);
		for (let i = 0; i < tiles.length; ++i) {
			totalValue[assignment[tiles[i]]] += tileValueCache[i];
		}

		let minVal = totalValue[0];
		let maxVal = totalValue[0];
		for (let j = 1; j < numRegions; ++j) {
			const v = totalValue[j];
			if (v < minVal) minVal = v;
			if (v > maxVal) maxVal = v;
		}
		const spread = maxVal - minVal;

		if (detailedLogs) {
			console.log(
				`Power diagram iter ${iter}: spread=${spread.toFixed(2)}, target=${targetValue.toFixed(2)}, damping=${damping.toFixed(2)}, values=[${Array.from(totalValue, (v) => v.toFixed(1)).join(", ")}]`,
			);
		}

		// Single-iter overshoot detector. Reused by the refit block above and
		// the damping adapt below. An overshoot iter has bias values that
		// pushed past equilibrium and value redistributed non-locally as a
		// result, so the observed dValue/dBias slope no longer reflects the
		// small-step responsiveness we're trying to measure -- the refit
		// must skip and damping must shrink.
		const overshoot = iter > 0 && spread > prevSpread + 1e-6;

		// Refit transferCoeff from a single-iter (prev -> this) sample.
		// Best-fit slope through the origin (least-squares, one degree of
		// freedom):
		//   observed = sum(dValue * dBias) / sum(dBias * dBias)
		// Using the signed dot product (rather than averaging |dValue/dBias|
		// per region) is what makes the cross-region coupling cancel
		// correctly: when one region's bias change also moves a neighbor's
		// value, the neighbor contributes a (dValue, dBias) pair with a
		// smaller |dBias| rather than getting double-counted. The clamp
		// keeps any single noisy sample from blowing up the estimate; the
		// running-average blend further smooths it over iters.
		if (iter > 0 && !overshoot) {
			let num = 0;
			let den = 0;
			for (let j = 0; j < numRegions; ++j) {
				const dBias = bias[j] - prevBias[j];
				const dValue = totalValue[j] - prevTotalValue[j];
				num += dValue * dBias;
				den += dBias * dBias;
			}
			if (den > 1e-9 && num > 0) {
				const observed = num / den;
				const clamped = observed < coeffLo ? coeffLo : observed > coeffHi ? coeffHi : observed;
				const alpha = 1 / (1 + calibrationConfidence);
				const next = (1 - alpha) * transferCoeff + alpha * clamped;
				if (detailedLogs) {
					console.log(
						`  Recalibrated transferCoeff: ${transferCoeff.toFixed(3)} -> ${next.toFixed(3)} (observed ${observed.toFixed(3)}, clamped ${clamped.toFixed(3)}, alpha ${alpha.toFixed(2)})`,
					);
				}
				transferCoeff = next;
				if (calibrationConfidence < calibrationConfidenceCap) ++calibrationConfidence;
			}
		}

		// Adapt damping. Overshoot halves it; a new global best grows it by
		// 1.4 toward maxDamping. Tie growth to best-improvement rather than
		// iter-over-iter improvement: a recovery iter often "improves" on the
		// previous bad iter without setting a new global best, and growing
		// damping there wastes the recovery.
		const improvedBest = spread < bestSpread - 1e-6;
		if (iter > 0) {
			if (overshoot) {
				damping *= 0.5;
				if (damping < minDamping) damping = minDamping;
			} else if (improvedBest) {
				damping *= 1.4;
				if (damping > maxDamping) damping = maxDamping;
			}
		}
		prevSpread = spread;

		// Snapshot if this is the best partition seen so far.
		if (improvedBest) {
			bestSpread = spread;
			bestAssignment.set(assignment);
			itersSinceBest = 0;
		} else {
			++itersSinceBest;
			if (itersSinceBest >= stagnationLimit) {
				console.log(`  Stopping early for stagnation: ${itersSinceBest} iters without improvement.`);
				break;
			}
		}

		// Early exit once spread is within 10% of target. Checked after the
		// snapshot so the current (best) assignment is preserved. Further iters
		// would polish single-tile flips at the cost of a full Dijkstra each.
		if (spread < earlyExitSpread) break;

		// Snapshot the bias array used for THIS iter before the update below
		// mutates it. Next iter's refit needs prevBias to hold the bias
		// values that *produced* totalValue (i.e. this iter's input), not the
		// next iter's input -- otherwise dBias and dValue describe different
		// regimes and the slope estimate is meaningless.
		prevBias.set(bias);
		prevTotalValue.set(totalValue);

		// Update biases. Linear correction: deltaBias = damping * imbalance
		// / transferCoeff. transferCoeff is our estimate of "value moved per
		// unit of bias change", so dividing the imbalance by it gives the
		// bias step that should close the gap. Underweight regions
		// (totalValue[j] < targetValue) get their bias raised, claiming more
		// tiles next iteration.
		//
		// Mean-center the deltas: only pairwise bias differences affect the
		// partition (uniform bias shifts produce identical Dijkstra output),
		// so subtracting the mean keeps bias magnitudes from drifting
		// unboundedly without changing dynamics. It also makes clamping
		// predictable -- otherwise the largest |delta| eats the budget first.
		let deltaSum = 0;
		for (let j = 0; j < numRegions; ++j) {
			const raw = (damping * (targetValue - totalValue[j])) / transferCoeff;
			const delta = raw > maxBiasDelta ? maxBiasDelta : raw < -maxBiasDelta ? -maxBiasDelta : raw;
			bias[j] += delta;
			deltaSum += delta;
		}
		const meanDelta = deltaSum / numRegions;
		for (let j = 0; j < numRegions; ++j) {
			bias[j] -= meanDelta;
		}
	}

	// Restore best-so-far if final iter wasn't the best.
	if (bestSpread < Infinity) {
		assignment.set(bestAssignment);
	}
}

// Phase 5: write `ctx.assignment + playerIdOffset` back into
// `hexMap.tiles[y][x].majorPlayerRegionId` for every assigned landmass tile.
function writeBack(ctx: LandmassContext, hexMap: HexMap, playerIdOffset: number): void {
	const { width, height, inLandmass, assignment } = ctx;
	const tiles = hexMap.getTiles();
	for (let y = 0; y < height; ++y) {
		const row = tiles[y];
		const rowOffset = y * width;
		for (let x = 0; x < width; ++x) {
			const idx = rowOffset + x;
			if (inLandmass[idx] === 1) {
				const r = assignment[idx];
				if (r >= 0) {
					row[x].majorPlayerRegionId = r + playerIdOffset;
				}
			}
		}
	}
}

// -----------------------------------------------------------------------------
// Driver
// -----------------------------------------------------------------------------
export function CreateMajorPlayerAreas(
	hexMap: HexMap,
	playerRegions: PlayerRegion[],
	valueFunction?: (tile: HexTile) => number,
	wrap: WrapDistOptions = { wrap: WrapType.None },
) {
	const perfScope: profileScope = new profileScope("Creating major player regions");

	const kmeansMaxPasses = 6;
	const partitionMaxIters = 12;

	VoronoiUtils.performanceMarker("createMajorPlayerAreas - Begin");
	let playerIdOffset = 0;

	// Build map-invariant context once (terrain, positions, neighbors).
	// Per-landmass work below only allocates the per-landmass masks.

	const mapCtx = buildMapContext(hexMap, wrap);

	for (const region of playerRegions) {
		if (region.playerAreas == 0) continue;

		// Phase 1: layer per-landmass masks onto the shared map context.
		const ctx = buildLandmassContext(mapCtx, hexMap, region);

		// Phase 2: drop enclaves cut off by impassable tiles, keep the largest.
		const landmassTiles = keepLargestComponent(ctx);

		console.log(
			`Requesting ${region.playerAreas} player areas on landmass ${region.id} with ${landmassTiles.tiles.length} tiles.`,
		);

		// Trivial case: single player on this landmass, mark and write back.
		if (region.playerAreas == 1) {
			const { tiles } = landmassTiles;
			for (const idx of tiles) {
				ctx.assignment[idx] = 0;
			}
			writeBack(ctx, hexMap, playerIdOffset);
			++playerIdOffset;
			continue;
		}

		// Per-tile value scoring closure. Takes a flat tile index; the
		// user-provided `HexTile` form is adapted by capturing the tile grid
		// here so phase code never sees `HexTile`. Default reads `ctx.terrain`
		// directly off the index.
		const width = ctx.width;
		const tileValue: (idx: number) => number = valueFunction
			? (
					(tiles) => (idx: number) =>
						valueFunction(tiles[(idx / width) | 0][idx % width])
				)(hexMap.getTiles())
			: (idx: number) => (ctx.terrain[idx] === TerrainType.Coast ? 0.5 : 1.0);

		// Phase 3: pick balanced seed positions via k-means relaxation.
		const seeds = kmeansRelaxSeeds(ctx, landmassTiles, region.playerAreas, kmeansMaxPasses);
		VoronoiUtils.performanceMarker("createMajorPlayerAreas - K-means Done");

		// Phase 4: bias-adjusted multi-source Dijkstra produces the final
		// connected, value-balanced partition in `ctx.assignment`.
		profileFunction("powerDiagramPartition", () =>
			powerDiagramPartition(ctx, landmassTiles, seeds, region.playerAreas, tileValue, partitionMaxIters),
		);
		VoronoiUtils.performanceMarker("createMajorPlayerAreas - Partition Done");

		// Phase 5: commit this landmass's assignments to HexMap.
		writeBack(ctx, hexMap, playerIdOffset);

		console.log(
			`Finished creating major player regions for region ${region.id}, (ids ${playerIdOffset} - ${playerIdOffset + region.playerAreas - 1}).`,
		);

		playerIdOffset += region.playerAreas;
	}
	perfScope.end();
}
